//! Renders a [`Bundle`] as the generated Rust module consumed by `gang-ui`.

use std::fmt;

use crate::bundle::{Bundle, Entry};

const HEADER: &str = "// Generated by gang-embed; do not edit.";
const PRELUDE: &str = "use crate::Asset;";
const TABLE_OPEN: &str = "pub(crate) static ASSETS: &[Asset] = &[";
const TABLE_EMPTY: &str = "pub(crate) static ASSETS: &[Asset] = &[];";
const TABLE_CLOSE: &str = "];";

impl Bundle {
    /// Renders the generated module source.
    ///
    /// `root` is the '/'-separated path from the directory of the generated file to the
    /// dist directory. Every `include_bytes!` path is `root` joined with the entry's
    /// dist-relative path, so it resolves relative to the generated file.
    #[must_use]
    pub fn render(&self, root: &str) -> String {
        Table { bundle: self, root }.to_string()
    }
}

/// The generated module for a [`Bundle`], written through [`fmt::Display`].
struct Table<'a> {
    bundle: &'a Bundle,
    root: &'a str,
}

impl fmt::Display for Table<'_> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{HEADER}\n\n{PRELUDE}\n\n")?;
        let entries = self.bundle.entries();
        if entries.is_empty() {
            return writeln!(f, "{TABLE_EMPTY}");
        }
        writeln!(f, "{TABLE_OPEN}")?;
        for entry in entries {
            write_entry(f, entry, self.root)?;
        }
        writeln!(f, "{TABLE_CLOSE}")
    }
}

/// Writes one `Asset { .. }` literal for `entry`.
fn write_entry(f: &mut fmt::Formatter<'_>, entry: &Entry, root: &str) -> fmt::Result {
    let path = &entry.path;
    writeln!(f, "    Asset {{")?;
    writeln!(f, "        path: {path:?},")?;
    writeln!(f, "        content_type: {:?},", entry.content_type)?;
    writeln!(f, "        etag: {:?},", entry.etag)?;
    write!(f, "        identity: ")?;
    write_include(f, root, path)?;
    writeln!(f, ",")?;
    write_variant(f, "br", entry.br, root, path)?;
    write_variant(f, "gz", entry.gz, root, path)?;
    writeln!(f, "        immutable: {},", entry.immutable)?;
    writeln!(f, "    }},")
}

/// Writes an optional `br`/`gz` field: `Some(include_bytes!(..))` when `present`, else `None`.
fn write_variant(
    f: &mut fmt::Formatter<'_>,
    name: &str,
    present: bool,
    root: &str,
    path: &str,
) -> fmt::Result {
    if present {
        write!(f, "        {name}: Some(")?;
        write_include(f, root, &format!("{path}.{name}"))?;
        writeln!(f, "),")
    } else {
        writeln!(f, "        {name}: None,")
    }
}

/// Writes `include_bytes!("<root>/<file>")` for a dist-relative `file`.
fn write_include(f: &mut fmt::Formatter<'_>, root: &str, file: &str) -> fmt::Result {
    let literal = format!("{root}/{file}");
    write!(f, "include_bytes!({literal:?})")
}
